    xml += '<mxCell id="e2" edge="1" parent="1" style="rounded=1;html=1;strokeWidth=1.5;strokeColor=#999999;endArrow=block;endFill=1;exitX=0.5;exitY=1;entryX=0.5;entryY=0;"><mxGeometry relative="1" as="geometry"><mxPoint x="360" y="122" as="sourcePoint"/><mxPoint x="360" y="145" as="targetPoint"/></mxGeometry></mxCell>'
    xml += '<mxCell id="n3" value="&lt;b&gt;枚举开停机组合&lt;/b&gt;&lt;br&gt;&lt;font style=&quot;font-size:9px;color:#888;&quot;&gt;电氢氨装置只有全额开机/停机两种状态&lt;/font&gt;" style="rounded=1;whiteSpace=wrap;html=1;fillColor=#FFFFFF;strokeColor=#7AAA7A;strokeWidth=1.5;fontSize=11;fontStyle=1;" vertex="1" parent="1"><mxGeometry x="180" y="145" width="360" height="42" as="geometry"/></mxCell>'
