    xml += '<mxCell id="e7" edge="1" parent="1" style="rounded=1;html=1;strokeWidth=1.5;strokeColor=#999999;endArrow=block;endFill=1;exitX=0.5;exitY=1;entryX=0.5;entryY=0;"><mxGeometry relative="1" as="geometry"><mxPoint x="360" y="477" as="sourcePoint"/><mxPoint x="360" y="500" as="targetPoint"/></mxGeometry></mxCell>'
    xml += '<mxCell id="n8" value="&lt;b&gt;24场景统计分析&lt;/b&gt;&lt;br&gt;&lt;font style=&quot;font-size:9px;color:#888;&quot;&gt;全满足/部分满足/全不满足 + 全年吨氨成本&lt;/font&gt;" style="rounded=1;whiteSpace=wrap;html=1;fillColor=#F0F4FA;strokeColor=#7B9FC0;strokeWidth=1.5;fontSize=11;fontStyle=1;" vertex="1" parent="1"><mxGeometry x="170" y="500" width="380" height="42" as="geometry"/></mxCell>'
    xml += '<mxCell id="e8" edge="1" parent="1" style="rounded=1;html=1;strokeWidth=1.5;strokeColor=#999999;endArrow=block;endFill=1;exitX=0.5;exitY=1;entryX=0.5;entryY=0;"><mxGeometry relative="1" as="geometry"><mxPoint x="360" y="542" as="sourcePoint"/><mxPoint x="360" y="565" as="targetPoint"/></mxGeometry></mxCell>'
    xml += '<mxCell id="n9" value="&lt;b&gt;输出结果&lt;/b&gt;&lt;br&gt;&lt;font style=&quot;font-size:9px;color:#888;&quot;&gt;最优产量 + 全年成本分布曲线 + 指标统计&lt;/font&gt;" style="rounded=1;whiteSpace=wrap;html=1;fillColor=#E8F0E8;strokeColor=#5A8A5A;strokeWidth=2;fontSize=11;fontStyle=1;" vertex="1" parent="1"><mxGeometry x="190" y="565" width="340" height="42" as="geometry"/></mxCell>'
